function demoMain(idx,label){
  var srcs=["int x = 42;","y = a + b;","return 1;"];
  var src=srcs[idx%srcs.length];
  var toks=src.match(/[a-z]+|\d+|[=+;]/g);
  return "["+label+"] lexed '"+src+"' -> ["+toks.join("|")+"] ("+toks.length+" tokens)";
}

